insert into public.questions (question_id,paper_id,question_number,question_type,question_points,question_text,option_a,option_b,option_c,option_d,option_e,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('112-3301-058','112-3301',58,'single_choice',2,'訴訟繫屬中為訴訟標的之法律關係已由被告移轉至第三人時，關於法院之處置，下列敘述，何者錯誤？','於第三人承受訴訟前，訴訟程序當然停止','第三人經兩造同意，得聲請代被告承當訴訟','如原告不同意第三人承當訴訟，被告或第三人均得聲請法院以裁定許可之','在第三人未參加或承當訴訟，及當事人未對其為訴訟告知時，法院知悉該項移轉，應即以書面將訴 訟繫屬之事實通知第三人',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-059','112-3301',59,'single_choice',2,'關於爭點整理程序，下列敘述，何者正確？','在準備程序要否由受命法官調查證據，可由合議庭裁量定之','在行合議審判之訴訟事件，不可在言詞辯論程序期日進行爭點整理','兩造當事人在起訴以前或訴訟外亦得成立簡化爭點之協議','受訴法院須先使兩造交換準備書狀，始得開始整理爭點',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-060','112-3301',60,'single_choice',2,'關於訴訟代理人，下列敘述，何者正確？','當事人委任律師為訴訟代理人，向法院提起民事訴訟，當事人於程序進行中死亡，訴訟程序當然停 止。該訴訟代理人在有繼承人承受訴訟前，不得為關於本案之訴訟行為','訴訟委任書若已記載「全權委任」字樣，該訴訟代理人即有和解、提起上訴及選任代理人之權限','由訴訟代理人終止訴訟委任，以書狀向法院陳報時即生效力，訴訟代理人嗣後再為之訴訟行為，均 不生效力','當事人雖不在法院之轄區內住居，但只要其受特別委任之訴訟代理人受送達之權限未受限制，且住 居法院所在地者，於計算法定期間時，即不得扣除在途期間',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-061','112-3301',61,'single_choice',2,'下列訴訟，何者得聲請法院裁定許可為訴訟繫屬事實之登記？','甲依買賣契約法律關係，訴請乙移轉A 地所有權','甲依所有物返還請求權，訴請乙返還無權占有之A 地','甲將A 地所有權移轉予乙後，以該物權移轉行為無效為由，依所有物妨害排除請求權，訴請乙塗銷 甲、乙間所有權移轉登記','甲以借名登記契約業經終止為由，訴請A 地登記名義人乙將A 地所有權移轉登記予甲',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-062','112-3301',62,'single_choice',2,'甲向乙公司購買之汽車有諸多瑕疵，在乙開設於A 地方法院管轄區域之保養廠維修多次未見改善， 甲擬向合意管轄之B 地方法院起訴請求減少價金。下列敘述，何者正確？','甲得於起訴前向本案訴訟管轄法院B 地方法院聲請保全證據，留置前述保養廠維修紀錄','法院駁回甲保全證據之聲請時，甲不得聲明不服','法院准許甲保全證據之聲請時，相對人乙得聲明不服','甲如於保全證據程序終結後逾30 日未對乙起訴，乙得向法院聲請裁定解除維修紀錄之留置',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-063','112-3301',63,'single_choice',2,'甲訴請判決命被告乙將A 地所有權移轉登記予甲，陳稱：某日，甲向乙購買A 地，約定價金為新臺 幣（下同）500 萬元，已付其中400 萬元，乙卻拒不辦理過戶，為此起訴等語。對此，乙請求判決駁 回甲之訴，抗辯稱：乙雖有出賣A 地之事，但甲尚未付清積欠之價金100 萬元云云。下列敘述，何者 錯誤？','在本訴訟，受訴法院在認為兩造之主張均屬可採時，應在判決主文寫明：乙應於甲給付其100 萬元 之同時，將A 地所有權移轉登記予甲等旨，而不得判決甲之請求為全部無理由','在受訴法院採用上述選項所示判決主文為判決並經確定時，乙得據此判決為執行名義對甲強 制執行','在本訴訟中，乙就其對甲之100 萬元價金債權，如不知其得提起反訴時，受訴法院應加以闡明','在訴訟中，乙抗辯系爭買賣契約已經解除，就甲所積欠之價金，得併為訴之聲明：如法院認為A 地 所有權移轉登記請求為有理由時，甲應給付乙100 萬元',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-064','112-3301',64,'single_choice',2,'甲訴請乙返還A 車，主張該車為甲所有，被乙無權占有，依所有物返還請求權為請求。下列敘述，何 者錯誤？','本件訴訟之原告已經表明訴訟標的為甲對乙之所有物返還請求權','如乙否認甲就A 車之所有權存在，則甲就其有A 車所有權之該當要件事實，應先具體陳述，然後 就乙所否認之具體事實，甲應負證據提出責任','在乙承認甲就A 車之所有權存在時，受訴法院不得據以認定甲有A 車所有權，而須再闡明甲就該 權利發生之要件事實為具體陳述並提出證據','在乙抗辯其就A 車對甲有租賃權，而甲否認乙有租賃權時，則乙就該租賃權發生之要件事實應為 具體陳述，然後就甲所否認之事實負證據提出責任',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-065','112-3301',65,'single_choice',2,'甲以其所有之A 地遭乙無權占有為由，依民法第767 條第1 項規定，起訴請求乙返還A 地（下稱前 訴訟），經法院於民國110 年12 月1 日判決（下稱系爭判決）甲勝訴，乙未上訴而確定。下列敘述， 何者正確？','甲於111 年2 月15 日，以乙於系爭判決言詞辯論終結前已無權占有A 地3 年為由，依民法第179 條規定，請求乙給付相當於租金之不當得利，已為系爭判決之既判力效力所及','乙於系爭判決確定後，起訴請求確認甲非A 地之所有權人，法院應依民事訴訟法第249 條第1 項 第7 款規定駁回該訴','乙以其於前訴訟事實審言詞辯論終結後與甲訂立租約，對甲起訴請求確認其就A 地之租賃權存在， 法院不受前訴訟系爭判決所認定乙乃無權占有A 地之拘束，得另為認定乙有租賃權','甲於111 年1 月2 日將A 地所有權移轉登記於丙，丙不得持系爭判決對乙強制執行返還A 地',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-066','112-3301',66,'single_choice',2,'關於法院之調解，下列敘述，何者正確？','法院之調解與訴訟上和解由於都是在法院進行，所以均僅由法官居中促成','就調解事件有利害關係之第三人，經法官之許可，得參加調解程序','於第二審時，僅能為訴訟上和解，不能試行法院之調解','醫療糾紛因當事人間並無一定情誼，且爭議很大，通常難能成立和解，故非為起訴前應經法院調解 之事件',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-067','112-3301',67,'single_choice',2,'關於簡化判決書之規定，下列敘述，何者錯誤？','簡易程序判決書之事實及理由，得合併記載其要領或引用當事人書狀、筆錄或其他文書，必要時得 以之作為附件','簡易程序中，本於當事人對訴訟標的之捨棄或認諾者，判決書得僅記載主文','簡易庭法官得於宣示判決時，命將判決主文及事實、理由之要領，記載於言詞辯論筆錄，不另作判 決書','小額程序之判決書，得僅記載主文，均無加記理由要領之必要',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-068','112-3301',68,'single_choice',2,'關於小額訴訟事件，下列何者，不屬法院得逕依一切情況認定事實為判決而不調查證據之情形？','經兩造同意者','該事件依法應行調解程序，被告經於調解期日5 日前受合法通知未到場，法院依職權由原告一造辯 論而為判決者','原告聲請調查之證據方法僅有詢問住在智利之證人1 名，因該證人臥病行動不便，需支出日費、旅 費新臺幣（下同）23 萬元','原告主張被告應支付房屋鄰損修繕費7 萬元，原告除聲請鑑定外，陳明無其他證據方法，經法院選 任臺北市建築師公會鑑定，該公會覆知鑑定需費時10 個月始能完成，鑑定費用為35 萬元',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-069','112-3301',69,'single_choice',2,'第一審法院為原告一部勝訴、一部敗訴之判決，原告就其敗訴部分提起第二審上訴。關於附帶上訴， 下列敘述，何者錯誤？','上訴合法者，被上訴人縱曾捨棄上訴權，仍可在言詞辯論終結前，提起附帶上訴','經第三審法院發回第二審法院，被上訴人在更審期間，不得提起附帶上訴','上訴因不合法經駁回，如附帶上訴已具備上訴之要件，不失其效力','附帶上訴如已具備上訴之要件，不因原告合法撤回起訴而失其效力',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-070','112-3301',70,'single_choice',2,'甲以乙為被告提起請求返還借款之訴訟，乙自認有收受甲交付之款項，但抗辯該款項並非基於消費借 貸關係，甲無借款返還請求權，若前開抗辯無理由，則以對甲之同額債權予以抵銷。第一審判決認甲 對乙有借款返還請求權，但乙所為抵銷抗辯可採，而駁回甲之訴。甲、乙均不服，各自提起第二審上 訴。下列敘述，何者正確？','甲於上訴狀內僅記載不服原判決，但未表明應如何廢棄或變更之聲明者，原第一審法院無須命補正， 應逕認上訴不合法，以裁定駁回上訴','甲未依法繳納上訴裁判費，經原第一審法院定期命甲補正，甲未補正，卷宗送至第二審法院後，審 判長仍應再定期命補正，於甲逾期未補正時，法院始得裁定駁回甲之上訴','乙因債權經抵銷始獲勝訴判決，仍屬受不利判決，有上訴利益','乙未於上訴狀內表明上訴理由，第二審法院審判長得定相當期間命乙提出理由書，如乙逾期未提出， 審判長得命乙以書狀說明理由，逾期未說明者，第二審法院應裁定駁回乙之上訴',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-071','112-3301',71,'single_choice',2,'關於上訴第三審，下列敘述，何者錯誤？','對第一審判決未提起上訴或附帶上訴之當事人，於第二審判決駁回上訴時，不得上訴','不服簡易訴訟程序之第二審判決，不論金額為何，均不得向最高法院提起上訴','當事人委任律師對第二審判決聲明上訴後20 日內，未提出上訴理由書者，原第二審法院無庸命其 補正，以裁定駁回之','上訴第三審，不得再為訴之變更或追加',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-072','112-3301',72,'single_choice',2,'關於第二審程序，下列敘述，何者正確？','採嚴格續審制，故上訴後除第一審判決違反法令外，當事人不得提出新攻擊或防禦方法','當事人僅能於言詞辯論期日撤回上訴','第一審訴訟程序有重大瑕疵，為維持審級利益之必要，第二審法院得廢棄發回原法院','上訴狀未表明上訴理由時，經第二審法院通知補正仍未補正，得逕以裁定駁回上訴',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-073','112-3301',73,'single_choice',2,'當事人對第二審法院依通常訴訟程序所為終局判決不服，提起第三審上訴，下列何者作為上訴理由， 須經第三審法院之許可？','判決斟酌A 書證之事實認定，違背證據法則','判決理由先認上訴人占有B 地是基於租賃關係為有權占有，復謂被上訴人基於所有物返還請求權 請求上訴人返還B 地有理由，前後矛盾','參與辯論之法官為甲、乙、丙，參與判決之法官為甲、乙、丁','上訴人係未成年人，在未經上訴人之法定代理人合法代理之情形下，第二審法院逕為本案判決',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-074','112-3301',74,'single_choice',2,'關於再審之訴或聲請再審，下列敘述，何者正確？','當事人於再審書狀中表明依民事訴訟法第496 條第1 項第1 款，提起再審之訴，應認已合法表明再 審理由','當事人於判決確定後第10 日，發現當日出刊之雜誌所載內容，恰可援為證據，不得據以為再審事由','當事人於民國110 年1 月20 日收受第三審法院判決，經請教律師後，於110 年3 月1 日知悉該確 定判決適用法規錯誤，其旋於翌日依民事訴訟法第496 條第1 項第1 款規定，對該確定判決提起再 審之訴，依最高法院裁判見解，並未逾不變期間','當事人就確定判決於民事訴訟法第500 條所定之再審不變期間末日，依民事訴訟法第496 條第1 項 第13 款提起再審之訴，即已合法提起再審，為求訴訟經濟、紛爭一次解決，依最高法院裁判見解， 可於訴訟進行中，併主張同條項第1 款之再審事由',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-075','112-3301',75,'single_choice',2,'關於民事訴訟之抗告，下列敘述，何者正確？','原裁定法院接獲當事人之抗告狀後，認抗告為有理由，可自行撤銷或變更原裁定','原裁定法院誤認抗告未逾期，將該抗告事件送交抗告法院，抗告法院應將該抗告事件退由原裁定法 院處理，不得逕為駁回抗告之裁定','當事人聲請保全證據，經原法院裁定駁回，當事人於收受該裁定10 日內未對之提起抗告，僅聲明 異議，應由原裁定法院以不合法裁定駁回該異議而結案','合法之抗告得停止原裁定之效力',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-076','112-3301',76,'single_choice',2,'下列何者，不得單獨聲請？','假執行','假處分','定暫時狀態處分','假扣押',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-077','112-3301',77,'single_choice',2,'丁在某銀行之帳戶內有新臺幣（下同）200 萬元存款，於其死亡後，繼承人甲列乙及丙為被告，起訴 請求法院裁判分割遺產，並主張乙帳戶內有300 萬元存款亦屬丁所有，應併列入遺產分割範圍，由繼 承人甲、乙及丙繼承等語（下稱本案請求）。下列敘述，何者錯誤？','關於如何分割遺產，雖法院裁判時不受甲主張之分割方法所拘束，乙或丙仍得提出遺產分割方案供 法院斟酌','在兩造就「乙帳戶內300 萬元存款為遺產」之事實有爭執時，甲應提出證據予以證明','乙、丙對甲之繼承權有爭執時，法院應曉諭原告或被告得併就繼承權存否請求裁判','受訴法院不得依職權將本案請求移付調解，當事人在調解程序亦不得合意聲請法院就本案請求為 裁定',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-078','112-3301',78,'single_choice',2,'甲夫、乙妻結婚後1 年，乙與丙男發生性關係，嗣產下一子丁。未成年之丁知悉此事後，欲否認其與 甲之父子關係。下列敘述，何者錯誤？','丁得向自己住所地之法院提起否認推定生父之訴','丁提起否認推定生父之訴，僅列甲為被告即足，無庸以乙為共同被告','於丁所提否認推定生父之訴，法院不應將訴訟事件及進行程度通知丙','於丁所提否認推定生父之訴，就甲及丁間血緣關係存否之爭執，法院認有必要時，得依職權命雙方 接受醫學上之檢驗',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-079','112-3301',79,'single_choice',2,'甲、乙係夫妻，曾以書面約定將坐落臺南市之A 屋登記為甲之名義所有，如將來因該財產涉訟，同意 由起訴時甲之住所地法院管轄。嗣甲、乙因感情破裂分居，甲住高雄市，乙住臺南市，但甲、乙二人 平日均在彰化市上班、生活。甲列乙為被告，向臺灣臺南地方法院（下稱臺南地院）民事庭起訴請求 確認甲就A 屋之所有權存在（前訴訟）。又，乙列甲為被告另向臺灣高雄少年及家事法院（下稱高雄 少家法院）起訴，請求判決准兩造離婚，並將夫妻財產酌予分配（後訴訟）。關於有無審判權或管轄 權之處理，下列敘述，何者正確？','因臺南地院就前訴訟有專屬管轄權，所以兩造一律不得合意聲請法院將前訴訟移送高雄少家法院為 合併審判','在高雄少家法院審理後訴訟之程序上，兩造爭執A 屋是否為兩造婚後所取得之財產，此時兩造得 合意聲請臺南地院將前訴訟移送於高雄少家法院為合併審判','在當事人尚未提起前訴訟及後訴訟以前，就該二訴訟，兩造不得以書面合意由臺灣彰化地方法院家 事法庭審判','臺南地院應依職權將前訴訟移送於受理後訴訟之高雄少家法院',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-080','112-3301',80,'single_choice',2,'關於婚姻事件程序，下列敘述，何者錯誤？','夫妻持續1 年以上在中華民國有共同之居所，縱其二人均非中華民國國民，由夫或妻所提離婚事件， 中華民國法院仍有審判管轄權','婚姻事件之夫或妻受監護宣告者，除能證明其有意思能力外，應由其監護人代為訴訟行為','離婚之訴，夫或妻於事實審言詞辯論終結前死亡者，因已無對立當事人，法院應以判決駁回原告之訴','撤銷婚姻之訴，原告於判決確定前死亡者，有權提起同一訴訟之他人，得於知悉原告死亡時起3 個 月內聲明承受訴訟，但原告死亡後已逾1 年者，即不得再承受訴訟',null,'民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-4301-001','112-4301',1,'single_choice',2,'A 有限公司有甲、乙及丙3 位股東，各出資新臺幣100 萬元，由甲擔任董事，下列關於乙、丙監督甲 業務執行之敘述，何者正確？','乙、丙得隨時向執行業務之股東質詢公司營業情形，但應共同為之','乙、丙得隨時查閱公司之財產文件、帳簿、表冊，但應共同為之','若甲違反競業禁止規定，自其所得產生後未逾1 年者，乙、丙得以經表決權過半數之決議，將甲為 自己或他人所為行為之所得，作為公司之所得','若甲執行業務，有重大損害公司之行為或違反法令或章程之重大事項，乙或丙得訴請法院裁判解任之',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-002','112-4301',2,'single_choice',2,'從事科技業之A 股份有限公司（下稱A 公司）持有B 股份有限公司（下稱B 公司）全部已發行股份。 B 公司因融資需要，債權人要求其須提供一定擔保。A 公司董事長甲考量B 公司為A 公司全資子公 司，故以A 公司所有土地為B 公司設定抵押。查A 公司章程並未有得對外保證條款。則依司法實務 見解，前開設定抵押行為是否合法？','合法，因B 公司為A 公司全資之子公司，經濟上本為一整體','不合法，因A 公司所有土地依法不得設定抵押予他人','合法，因A 公司並非為保證人，不違反公司法規定','不合法，因A 公司章程未有得對外保證條款',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-003','112-4301',3,'single_choice',2,'甲為專門處理商事案件的律師，近來其客戶業績蓬勃發展，紛紛想轉換組織型態以因應公司資本與組 織之需求，甲身為A、B、C、D 四間公司之律師，就客戶需求之建議，下列敘述何者錯誤？','A 公司為有限公司，想轉換公司型態，甲建議A 公司必須取得股東表決權過半數之同意後可轉換 為股份有限公司，並應向公司的債權人分別通知及公告','B 公司為兩合公司，想轉換公司型態，甲建議B 公司取得三分之二以上股東之同意變更章程，將 該公司變更為有限公司或股份有限公司','C 公司為家族經營的股份有限公司，想轉換公司型態，甲建議該公司得經代表已發行股份總數三分 之二以上股東出席之股東會，以出席股東表決權過半數之同意，變更為閉鎖性股份有限公司','D 公司為閉鎖性股份有限公司，想轉換為一般股份有限公司，甲建議D 公司得經有代表已發行股 份總數三分之二以上股東出席之股東會，以出席股東表決權過半數之同意，即可為之',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-004','112-4301',4,'single_choice',2,'下列何者非屬公司負責人？','依公司法第173 條報經主管機關許可自行召集股東會之少數股東','依公司法第245 條聲請法院選派檢查公司業務帳目及財產情形之檢查人','有限公司之經理人但未兼任該公司董事','法院依公司法第208 條之1 選任之臨時管理人',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-005','112-4301',5,'single_choice',2,'A 有限公司於民國110 年初設立，原本無設立分公司之規劃，未於章程中記載分公司設立之相關事項。 於同年底，未先變更章程便於嘉義設立分公司，則設立分公司之效力如何？','無效','效力未定，須俟章程變更後始生效力','無對抗效力','有效',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-006','112-4301',6,'single_choice',2,'甲支持自己的一雙子女乙、丙創業，乙成立了非公開發行之A 股份有限公司（下稱A 公司），丙成立 了B 閉鎖性股份有限公司（下稱B 公司），甲對A、B 公司各出資一千萬元而取得A、B 公司的複數 表決權特別股，但為了避免子女缺乏商場經驗、輕率魯莽導致公司經營不善虧損連連，甲要求擔任A、 B 公司的監察人。下列敘述何者錯誤？','關於公司的董事選舉，A 公司之選舉只能採取累積投票制，B 公司得以章程排除累積投票制','關於公司監察人選舉，甲在B 公司之特別股擁有複數表決權，但在A 公司之特別股，其表決權與 普通股股東之表決權同','為了保障公司經營與股權穩定，A、B 公司均可發行限制轉讓之特別股予甲','為了節省公司經營成本，A、B 公司均得以章程允許股東會與董事會透過視訊或書面開會',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-007','112-4301',7,'single_choice',2,'股份有限公司之股東，欲請求公司監察人為公司對違法之董事提起訴訟，至少應具備下列何種資格？','繼續6 個月以上，持有已發行股份總數1%以上之股東','繼續6 個月以上，持有已發行股份總數3%以上之股東','繼續1 年以上，持有已發行股份總數1%以上之股東','繼續1 年以上，持有已發行股份總數3%以上之股東',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-008','112-4301',8,'single_choice',2,'關於公司法第172 條之1 的股東提案權，下列敘述何者正確？','股東提案權非股東之固有權，得以章程限制或免除','股東提案權為少數股東權，限持股百分之三以上之股東方可提案','只限股東常會，股東才享有提案權','董事會對於股東之提案，如不列入議案時，應於股東會後說明未列入之理由',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-009','112-4301',9,'single_choice',2,'A 公司持有B 公司已發行有表決權股份總數之百分之六十，A 公司及B 公司分別持有C 公司已發行 有表決權股份總數之百分之三十。甲雖持有C 公司已發行股份總數之百分之三，但全部皆為無表決權 股份。若A 公司基於對C 公司之控制力，促使C 公司以市價五成之價格賤賣其不動產給B 公司，且 未於該會計年度終了時對C 公司為適當補償，下列敘述何者錯誤？','A 公司及其負責人應就C 公司之損害負連帶賠償責任','B 公司於其所受利益限度內，就A 公司應負之損害賠償責任，應連帶負責','C 公司之債權人得以自己名義行使C 公司對A 公司及其負責人之求償權，請求對C 公司為給付','甲得以自己名義行使C 公司對A 公司及其負責人之求償權，請求對C 公司為給付',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-010','112-4301',10,'single_choice',2,'A 股份有限公司（下稱A 公司）為B 股份有限公司（下稱B 公司）百分之百持股之從屬公司。B 公 司擬以A 公司為存續公司，吸收合併C 股份有限公司（下稱C 公司），但此宗合併案受到B 公司股 東甲、C 公司股東乙反對。若此宗合併案通過後，甲、乙何人能主張股份收買請求權？','甲','乙','甲與乙皆可','甲與乙皆不可',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-011','112-4301',11,'single_choice',2,'A 股份有限公司（下稱A 公司）為上市公司，欲召開股東常會，下列何事項A 公司得以臨時動議提出？','董事甲欲擔任與A 公司營業範圍相同之競爭B 公司之董事長','A 公司欲增加其章程所定之股份總數','A 公司欲將年度應分派之股息以發行新股方式為之','A 公司欲以股東會決議之方式同意本次轉投資後，公司轉投資總額為實收股本百分之五十',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-012','112-4301',12,'single_choice',2,'A 股份有限公司（下稱A 公司）雖握有公司產品科技之重要專利，但是隨著科技推陳出新，舊有的技 術無法趕上時代，A 公司逐漸失去市場上的優勢，股價一落千丈。上個月A 公司突然發生債務無法清 償的財務危機，致公司岌岌可危而欲重整，關於重整的規定，下列敘述何者錯誤？','為了保障員工的權益，A 公司三分之二以上之受僱員工可以為公司聲請重整','公司負債過於龐大，繼續6 個月以上相當於公司已發行股份總數金額達百分之五之公司債權人可以 向法院聲請重整','一旦法院裁定重整，A 公司原有的股東會、董事、監察人所有職權都必須停止','法院裁定重整後，重整人應擬訂重整計畫，連同公司業務及財務報表，提請由股東與債權人組成的 重整關係人會議審查',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-013','112-4301',13,'single_choice',2,'非公開發行股票之A 公司，董事均由股東親自擔任，公司主要營運地點於海外，日常業務之經營則均 委由總經理決定。董事均事務繁忙，為求簡便，已修改章程允許公司董事會得採取書面會議。本次對 於法務經理之聘任案，公司欲採用書面會議決定，5 名董事中有3 名贊成採書面會議方式並表示同意 此一聘任案。其餘2 名董事不贊成書面會議方式並表示反對此一聘任案。下列敘述，何者正確？','本次會議合法，因章程已規定得採取書面會議','本次會議不合法，贊成採書面會議之董事人數不足法定成數','本次會議不合法，因未有三分之二以上董事贊成此一聘任案','本次會議合法，因已有過半數董事贊成此一聘任案',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-014','112-4301',14,'single_choice',2,'A 股份有限公司（下稱A 公司）董事甲，違法執行職務導致公司受損，股東會擬決議解任之。公司法 有關解任董事之規定，下列敘述何者錯誤？','A 公司股東會如欲通過解任董事甲之議案，其股東會應以特別決議為之','A 公司股東會如未通過解任董事甲之議案，股東乙欲提起解任董事之訴，至少須持有已發行股份總 數百分之三之股份','A 公司股東會如未通過解任董事甲之議案，符合持股條件之股東如欲訴請法院裁判解任甲，應於股 東會後30 日內為之','A 公司股東會如未通過解任董事甲之議案，監察人得隨時提起解任董事之訴',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-015','112-4301',15,'single_choice',2,'A 公司與B 公司均為非公開發行之股份有限公司，雙方均知悉有相互投資之事實。A 公司已發行股份 總數共3,000 萬股，B 公司已發行股份總數共1,500 萬股，均為有表決權股份。若A 公司持有B 公司 600 萬股，B 公司持有A 公司1,000 萬股，均非因盈餘或公積增資配股所得之股份，則A 公司於B 公 司股東會最多得行使表決權之股份數為多少？','500 萬股','300 萬股','200 萬股','0 股',null,'公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-016','112-4301',16,'single_choice',2,'甲以其房屋向A 產物保險股份有限公司（下稱A 公司）投保火災保險，並約定保險金額為新臺幣（下 同）1,000 萬元。其後甲屋發生火災以致房屋部分毀損，損失900 萬元，甲為避免損失進一步擴大， 支出必要費用720 萬元，該屋並經A 公司鑑價，其保險標的價值為1,500 萬元。下列敘述何者正確？','A 公司就甲所支出之必要費用720 萬元，應全額償還','A 公司就甲屋之損失應依其責任比例賠償600 萬元，但就甲為減輕損害所支出之必要費用720 萬 元應全額償還，共計1,320 萬元','A 公司就甲屋之損失應依其責任比例賠償600 萬元，就甲為減輕損失所支出之必要費用依其比例 償還480 萬元，然其給付金額以保險金額為上限，共計1,000 萬元','A 公司就甲屋之損失應依其責任比例賠償600 萬元，就甲為減輕損失所支出之必要費用依其比例 償還480 萬元，共計支付1,080 萬元',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-017','112-4301',17,'single_choice',2,'甲父以其未出嫁而同居一家之女兒乙為被保險人投保終身人壽保險，並指定甲為受益人。於保險有效 期間，乙結婚並與其配偶丙搬離娘家。數年後，乙死亡。下列敘述何者正確？','甲不得請求保險給付，因乙出嫁與其配偶丙成家後，保險契約效力即行終止','甲得請求保險給付，乙之出嫁並與配偶丙成家並不影響保險契約之效力，因人身保險僅在締結保險 契約時具有保險利益即可','甲不得請求保險給付，因乙出嫁與其配偶丙成家後，甲即喪失受益人資格，此時保險金為乙之遺產','甲得請求保險給付，乙雖出嫁與其配偶丙成家，但對甲仍負有扶養義務，故保險人應在乙之扶養義 務範圍內給付甲保險金',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-018','112-4301',18,'single_choice',2,'甲展售高價鑽錶一批，與乙簽訂保全服務契約，並向A 保險公司投保商業動產流動綜合保險。因乙之 過失，保全系統失效，致鑽錶失竊。A 保險公司於賠付保險金後，得否向乙主張代位權？','可，因甲對乙具有損害賠償請求權','可，但僅以甲對乙有侵權行為損害賠償請求權為限','不可，因甲對乙的請求權基礎係基於契約關係','不可，因甲對乙的請求權係基於侵權行為損害賠償請求權',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-019','112-4301',19,'single_choice',2,'A 保險公司欲投資不動產，依目前保險法之規定，下列敘述何者錯誤？','其投資總額，除自用不動產外，不得超過其資金百分之三十','購買之自用不動產總額不得超過其業主權益之總額','保險業對不動產之投資，以所投資不動產能即時利用為限，但不以立即有收益為必要','對不動產之取得及處分，應經合法之不動產鑑價機構評價',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-020','112-4301',20,'single_choice',2,'A 公司以其所有甲畫家之畫作向B 產物保險股份有限公司（下稱B 公司）投保藝術品保險，雙方約 定採定值方式投保，保險金額新臺幣（下同）100 萬元。保險期間因乙縱火導致該畫作焚毀無法修復， B 公司於給付保險金100 萬元後，即向乙代位求償，經鑑定後該畫作僅值90 萬元。試問：B 公司得 向乙代位求償之金額為何？','10 萬元','90 萬元','100 萬元','B 公司不得代位，因B 公司已從A 公司收取保險費',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-021','112-4301',21,'single_choice',2,'甲經體檢發現自身甲狀腺腫大，乃以自己為被保險人，指定其妻乙為受益人，投保死亡保險，但對要 保書之詢問隱匿此項檢查異常情況。然一年後甲發生重大車禍，不治死亡。乙向保險人請求保險金， 保險人發現甲於投保時不實說明，得否拒絕理賠？','保險人得拒絕理賠，但乙可主張自己善意不知情','保險人依保險法第64 條規定解除契約後即無須理賠','因甲之死亡與其違反據實說明義務間並無因果關係，保險人不得拒絕理賠，但得請求賠償因此所受 之損害','乙得證明甲之死亡並非基於其所隱匿之體況，保險人仍應給付保險金',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-022','112-4301',22,'single_choice',2,'A 醫院向B 保險公司投保醫院綜合責任險，保險金額每一事故新臺幣（下同）300 萬元。甲女就診期 間因施打麻醉劑休克死亡，A 醫院在B 保險公司人員參與下與甲女家屬達成600 萬元和解。嗣後，B 保險公司以參與和解當時其並未明示或默示同意和解金額為由，拒絕A 醫院之理賠申請。下列關於 本責任保險人和解參與權之敘述，何者正確？','參與權包括保險人之和解參加權及和解同意權二權利，亦即保險人未同意和解，保險人不受該和解 之拘束','參與權包括保險人之和解參加權及和解同意權二權利，亦即保險人未同意和解，保險人免除其理賠 責任','參與權僅包括和解參加權，不包括和解同意權，保險人一旦參與和解，保險人即應受和解效力之拘束','參與權僅包括和解參加權，不包括和解同意權，保險人參與和解，除有正當理由得拒絕和解條件或 其他除外不保理由外，保險人在保險金額範圍內應受和解之拘束',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-023','112-4301',23,'single_choice',2,'甲以其14 歲女兒乙為被保險人，向A 保險公司投保人壽保險，該契約效力為何？','效力未定，須待乙滿15 歲時契約方生效','契約無效','乙未滿15 歲，死亡險部分無效，其他部分若能單獨成立，則仍然有效','契約有效，但除喪葬費用之給付外，其餘死亡給付之約定於乙滿15 歲時始生效力',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-024','112-4301',24,'single_choice',2,'甲以自己為被保險人投保人壽保險，並指定其配偶乙為受益人，保險契約中有條款約定，變更受益人 須以書面申請並經保險公司同意且批註後始生效力。於保險期間，甲以書面申請變更受益人為其母校 A 大學，但在保險公司未批註後即死亡。依目前保險法令及通說見解，下列敘述，何者正確？','保險契約之受益人已變更為A 大學，故A 大學有保險給付請求權','因保險公司未完成批註，保險契約之受益人仍為乙，故乙有保險給付請求權','因A 大學與甲之間並無保險利益，故此變更受益人不生效力，保險契約之受益人仍為乙，故乙有保 險給付請求權','保險公司雖收受受益人變更申請書，但保險契約之受益人變更尚須保險人同意始生效力，故乙有保 險給付請求權',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-025','112-4301',25,'single_choice',2,'下列關於再保險之敘述，何者錯誤？','再保險依其性質應為責任保險','原保險契約與再保險契約得以條款約定，原保險契約之被保險人於保險人無法履行保險責任時，得 向再保險人請求','再保險人不得向原保險契約之要保人請求交付保險費','原保險契約得以條款約定，再保險不履行其給付義務時，保險人得拒絕或延遲其保險金給付義務',null,'保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-026','112-4301',26,'single_choice',2,'甲簽發金額新臺幣（下同）10 萬元，A 為付款人，一個月後到期之匯票予乙作為購買其二手車之部分 價金。後因家人反對購買二手車而解除契約，並賠償乙現金8 千元以彌補其損失。乙告知甲已將該票 銷毀，然事實上卻將該票空白背書轉讓予善意之丙，以償還其所積欠款項。丙隨後得知丁近日與朋友 共同創立公司，隨即又再將該票直接交付並贈與善意之丁，表示鼓勵年輕人創業。若該票到期不獲付 款，下列敘述何者正確？','丁得對甲及乙行使追索權','丁僅得對甲行使追索權，不得對乙行使追索權','丁僅得對乙行使追索權，不得對甲行使追索權','因丁為無償取得，故丁對甲及乙均不得行使追索權',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-027','112-4301',27,'single_choice',2,'依票據法第22 條規定，關於利益償還請求權之敘述，下列何者正確？','利益償還請求權人以最後之被背書人為限','匯票、本票之發票人及其保證人，支票之發票人、匯票之承兌人均為利益償還請求權之償還義務人','執票人得就其所受損害行使利益償還請求權','票據上之權利，係依票據法因時效或手續之欠缺而消滅時，執票人始得主張利益償還請求權',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-028','112-4301',28,'single_choice',2,'甲簽發一紙以A 為付款人之匯票予受款人乙，乙背書讓與丙，丙再背書讓與丁，丁則委任取款背書予 戊。當戊向A 付款提示而被拒付時，戊不得向下列何人主張票據責任？','甲','乙','丙','丁',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-029','112-4301',29,'single_choice',2,'甲簽發匯票一紙交付給乙，依序由乙、丙、丁記名背書，執票人戊之子己趁戊不注意時，將其好友丙 之簽名塗銷，若匯票於到期日不獲付款，戊可向下列何人行使追索權？','僅甲、乙','僅甲、乙、丁','僅甲、乙、丙、丁','僅甲、乙、己',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-030','112-4301',30,'single_choice',2,'甲簽發一張以A 為付款人之匯票交付予乙，乙除背書外並請求B 在票據上簽名為其保證，然後將票 據轉讓予丙，丙除背書外於該票記載在付款地的C 為預備付款人，然後將該票據轉讓予丁，丁於到期 日前向A 請求承兌遭拒，丁得對何人行使期前追索權？','甲、乙、丙、A、B','甲、乙、丙、B、C','甲、乙、丙、B','甲、乙、丙、C',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-031','112-4301',31,'single_choice',2,'房客甲所承租之房屋，大門門鎖損壞，向房東乙請求支付更換費用新臺幣1 萬元，乙不願支付。爭議 經調解後，乙勉為同意支付半價，惟刻意不肯支付現金，而開立3 個月期本票予甲，意圖刁難；甲以 乙之配偶丙須擔任票據保證人為條件，而答應接受本票。本票到期後，乙仍不願支付，甲依票據法及 司法實務，可如何救濟？','甲得向乙丙追索，並聲請法院裁定後強制執行乙丙財產','甲得逕向丙追索，並聲請法院裁定後強制執行丙財產','甲於向乙追索無效後，得向丙追索，並聲請法院裁定後強制執行丙財產','甲得向乙丙追索，追索無效後，得聲請法院裁定後強制執行乙財產',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-032','112-4301',32,'single_choice',2,'臺北市A 公司董事長甲簽發該公司以桃園市B 銀行為付款人之支票予乙，作為買賣價金，票載發票 日為105 年4 月1 日，其後乙再將該支票背書轉讓予丙，甲於105 年4 月10 日發現貨物有顯著瑕疵， 即通知乙解除買賣契約，並同時通知B 銀行撤銷付款之委託，丙於105 年4 月18 日向B 銀行提示未 獲付款，下列敘述，何者正確？','丙之付款提示未逾法定提示期間','如付款銀行B 拒絕付款，丙得對乙行使追索權','如付款銀行B 拒絕付款，丙喪失對甲的追索權','付款銀行B 不得付款',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-033','112-4301',33,'single_choice',2,'甲簽發劃有平行線支票一張予乙，乙背書轉讓予丙，丙再背書轉讓予丁時，丁要求丙將平行線撤銷， 依票據法規定，下列敘述何者正確？','該支票不得撤銷平行線','甲在平行線內簽章即可撤銷','乙在平行線內簽章即可撤銷','丙在平行線內簽章即可撤銷',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-034','112-4301',34,'single_choice',2,'甲簽發記名匯票一紙予乙，票面金額新臺幣100 萬元整，乙背書轉讓予丙，若丙背書轉讓予丁時，丙 於背書時所為之下列何項行為，將使丙之背書不生效力？','將乙之背書塗銷','記載戊為預備付款人','丙背書旁附記「丁應依契約履約，否則本背書無效」','丙背書旁註記「轉讓金額新臺幣80 萬元」',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-035','112-4301',35,'single_choice',2,'甲簽發一紙以民國105 年10 月1 日為到期日，並記載乙為受款人之本票，交付給乙後，乙又將該本 票交付轉讓給丙，丙擅自偽造乙之背書，並將到期日更改為同年9 月1 日後背書轉讓給善意的丁，丁 於同年9 月1 日向甲提示付款被拒，下列敘述，何者正確？','依該票據外觀，其背書連續，且因屆期未獲付款，故丁得持該票據對甲、乙及丙行使追索權','依該票據外觀，其背書連續，但乙得以背書被偽造為由對抗丁，不用負票據責任','因乙之背書是被偽造，該票據之背書不連續，故丁無法行使任何票據權利','因乙之背書是被偽造，該票據之背書不連續，但乙背書之偽造不影響其他真正簽名者之效力，故丁 僅得對丙行使追索權',null,'票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-036','112-4301',36,'single_choice',2,'股票上市之A 股份有限公司（下稱A 公司）董事長甲，知悉足以影響該公司股價之消息，於該消息公 開前，以新臺幣（下同）100 元買進該公司股份10,000 股，迄今尚未賣出，該消息公開後翌日，A 公司 股票收盤價為115 元，消息公開後10 個營業日A 公司股票平均收盤價為140 元，若甲之行為被法院認 定構成內線交易，依最高法院大法庭之見解，計算甲之內線交易犯罪所得之敘述，下列何者正確？','甲未賣出，故無犯罪所得','計算犯罪所得時，不應扣除證券交易稅及手續費','甲之犯罪所得採擬制所得法計算','若有該內線消息以外因素影響A 公司股價，應將該因素影響之股價自犯罪所得中扣除',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-037','112-4301',37,'single_choice',2,'A 上市公司（下稱A 公司）為激勵優秀員工，擬採行庫藏股制度，使員工經由取得股份，對公司產生 向心力，下列敘述何者合法？','得經董事會三分之二以上董事之出席及出席董事超過二分之一同意，向A 公司之大股東買回股份','A 公司買回股份之數量比例，不得超過該公司已發行股份總數百分之一','A 公司收買股份之總金額，不得逾法定盈餘公積','A 公司收買自己之股份轉讓於員工時，得限制員工在一定期間內不得轉讓。但其期間最長不得超過 2 年',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-038','112-4301',38,'single_choice',2,'A 上市公司（下稱A 公司）近期以私募股份之方式，籌措公司投資所需之資金。甲為此次A 公司私 募有價證券之購買人。依證券交易法之規定，下列敘述何者錯誤？','此次有價證券私募應經股東會通過，且公司得於該股東會決議之日起2 年內，分次辦理','此次有價證券私募，該公司之員工及原股東並無優先認購權','A 公司只要在私募有價證券之價款繳納完成日起15 日內，檢附相關書件，報請主管機關備查即可， 無須事先向主管機關申報','若甲持有該私募有價證券尚未滿3 年，得以私人間之直接讓受，其數量不超過該證券一個交易單位， 前後2 次之讓受行為，相隔不少於3 個月之方式賣出',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-039','112-4301',39,'single_choice',2,'關於證券交易法規範之對象，下列敘述何者錯誤？','募集設立之公司在設立登記前，發起人不負發行人責任','外國公司係以營利為目的，依照外國法律組織登記之公司','公司制證券交易所之組織，以股份有限公司為限','除兼營之金融機構外，證券商須為股份有限公司',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-040','112-4301',40,'single_choice',2,'A 公司為一家從事汽車輪胎生產的上市公司，該公司設有甲、乙、丙、丁、戊5 名董事。依證券交易 法之規定，下列敘述何者錯誤？','公開發行公司董事會之董事人數不得少於5 人，故A 公司不得以章程降低董事人數','除經主管機關核准者外，甲、乙、丙、丁、戊5 名董事間應有超過半數之席次，不得具有配偶或三 親等以內之親屬關係','法人為A 公司之股東時，除經主管機關核准者外，不得由其代表人同時當選或擔任公司之董事及 監察人','若甲、乙、丙、丁、戊5 人中有2 人解任，則A 公司應自事實發生之日起60 日內，召開股東臨時 會補選之',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-041','112-4301',41,'single_choice',2,'A 上市公司今年第一季財務報告，因隱匿重要內容而有不實。關於財報不實責任之敘述，下列何者正確？','總經理甲故意違法，其應依其責任比例負賠償責任','董事長乙如能證明已盡相當注意，且有正當理由可合理確信其內容無隱匿情事者，免負賠償責任','財務報告之核閱會計師丙若不能證明自己已經合理調查，並有正當理由確信其核閱意見為真實者， 即應負賠償責任','請求賠償之原告須能證明在本財務報告簽章之職員丁有不正當或過失行為，方可要求丁負損害賠償 責任',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-042','112-4301',42,'single_choice',2,'A 上市公司之某次審計委員會中，下列議案均未獲審計委員會全體成員二分之一以上同意，下列何項 議案不得由全體董事三分之二以上同意行之？','經董事長、經理人、會計主管簽名或蓋章之年度財務報告案','財務主管甲之任命案','簽證會計師乙之委任案','重大之資產或衍生性商品交易案',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-043','112-4301',43,'single_choice',2,'我國證券市場發展日益興盛，營運多樣之證券商居功不少，而各種類型證券商所面對的管制亦有不同， 依照證券交易法，下列敘述何者錯誤？','證券承銷商辦理有價證券之承銷','證券經紀商辦理有價證券買賣之行紀、居間、代理、承銷','證券自營商辦理有價證券之自行買賣','證券交易法下證券商可以區分為證券承銷商、證券自營商、證券經紀商等三種',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-044','112-4301',44,'single_choice',2,'A 上市公司（下稱A 公司）為了擴大公司競爭力、發展垂直經濟，而B 上市公司（下稱B 公司），具 有良好體質與市場潛力，因此A 公司擬針對B 公司進行公開收購，但在過程中，因為發生一些情況， 需要改變公開收購條件，依證券交易法之規定，下列何者改變條件原則上屬於合法？','調降公開收購價格','降低預定公開收購有價證券數量','延長公開收購期間','縮短公開收購期間',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-045','112-4301',45,'single_choice',2,'A 公司為一家從事乳品販售之上市公司，該公司設有甲、乙、丙、丁、戊、己、庚、辛、壬9 名董事， 其中甲、乙、丙、丁、戊5 人為獨立董事。A 公司並設有審計委員會。依證券交易法之規定，下列敘 述何者正確？','A 公司得由甲、乙、丙3 名獨立董事組成審計委員會','A 公司審計委員會成員中至少1 人應具備會計或財務專長','A 公司董事會不得變更審計委員會之決議','A 公司審計委員會成員對其職權所有事項，均得各自獨立行使',null,'證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-046','112-4301',46,'single_choice',2,'已經假扣押執行之財產，受政府機關依法強制徵收。下列敘述，何者錯誤？','假扣押之執行效力，繼續存在於該財產因政府機關強制徵收後之代替利益','執行法院應將其補償金額提存','假扣押債權人之債權，不因強制徵收而受影響','假扣押債權人以其債權對於政府機關強制徵收後之代替利益為終局執行時，毋須另行取得執行名義',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-047','112-4301',47,'single_choice',2,'債權人甲持對債務人乙之執行名義，向臺灣彰化地方法院民事執行處（下稱彰化地院）聲請查封拍賣 乙所有A 地，於民國112 年6 月6 日進行第一次拍賣，丙出價最高，但未於記載受款人為丙之保證 金記名支票背書。彰化地院諭知丙之投標為廢標，由次高標之丁得標，丙當場聲明異議。下列敘述， 何者正確？','彰化地院應以拍賣程序業已終結，丙聲明異議不合法為由，裁定駁回其聲明異議','彰化地院應詢問丙是否同意於保證金支票補正背書，經其補正背書後，諭知由丙得標','彰化地院應不詢問丙之意見，逕認其投標為有效，依強制執行法第13 條第1 項規定更正處分，由 丙得標','彰化地院應以丙之保證金支票背書不連續，於開標後不能補正，其投標為廢標為由，裁定駁回其聲明 異議',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-048','112-4301',48,'single_choice',2,'債權人甲持金錢債權執行名義，聲請法院就債務人乙所有之A 屋為強制執行，該屋拍賣由丙拍定繳 清價款後，法院發給權利移轉證書。下列敘述，何者正確？','如點交時發現A 屋係海砂屋，丙得請求法院撤銷拍賣','如點交時發現A 屋係海砂屋，丙得請求法院減少拍賣價金','如點交時發現A 屋於法院核發權利移轉證書前已滅失，丙得請求法院撤銷拍賣','如點交時發現A 屋於法院核發權利移轉證書後滅失，丙得請求法院解除拍賣',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-049','112-4301',49,'single_choice',2,'甲於民國112 年5 月5 日以其所有A 地，設定第一順位最高限額抵押權新臺幣（下同）600 萬元予 乙，供其向乙借款500 萬元之擔保。嗣丙持法院對甲核發之確定支付命令，聲請臺灣彰化地方法院民 事執行處（下稱彰化地院）強制執行A 地後，復由甲之另一債權人丁持確定終局判決，聲請彰化地院 對該地為強制執行。彰化地院合併其執行程序，嗣由戊拍定並繳清價金。下列敘述，何者錯誤？','倘彰化地院已知乙之借款500 萬元未受清償，應將其金額列入分配，應徵收之執行費，於執行所得 金額扣繳之','丙繳交之執行費，得就A 地拍賣所得價金優先受清償','丙取得支付命令之費用，得就A 地拍賣所得價金優先受清償','丁屬再聲請強制執行之債權人，其繳交之執行費，得就A 地拍賣所得價金優先受清償',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-050','112-4301',50,'single_choice',2,'甲訴請乙應容忍其通行乙所有之A 地，獲勝訴判決確定後，乙在該地上設置路障，阻礙甲之通行，甲 聲請法院強制執行。下列敘述，何者錯誤？','執行法院得處乙怠金','乙經執行法院處怠金後，仍不履行時，執行法院得再處怠金或管收之','甲得聲請法院拆除乙在A 地上所設置之該路障','執行法院得定期命乙拆除路障，於不履行時，逕予管收',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-051','112-4301',51,'single_choice',2,'有關假處分之執行，下列敘述，何者錯誤？','假處分之執行，應於假處分之裁定送達同時或送達前為之','債權人收受假處分裁定後，應於30 日內聲請強制執行','假處分之裁定一經廢棄，執行法院不待債務人聲請，即應撤銷其已實行之執行處分','假處分裁定為禁止債務人為一定之行為者，執行法院應將該裁定送達於債務人',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-4301-052','112-4301',52,'single_choice',2,'甲分別向乙、丙、丁各借款新臺幣（下同）100 萬元，屆期均未清償。乙持假扣押裁定向法院聲請查 封甲所有之A 地，丙取得確定之支付命令後執以向法院聲請對A 地為強制執行。A 地經法院拍賣得 價金200 萬元。下列敘述，何者錯誤？','乙就該拍賣價金得受分配，惟其分配之金額應予提存','丁於A 地拍定前即已取得執行名義，惟於A 地拍定後始聲明參與分配，就該地拍賣價金仍得受分配','執行法院就丙所聲請之強制執行，無庸重覆進行查封程序，得逕行換價程序','乙之假扣押執行程序並不妨礙丙之終局執行程序',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-4301-053','112-4301',53,'single_choice',2,'為執行名義之確定判決主文為：「甲應於乙給付新臺幣二千萬元之同時，將A 地所有權移轉登記予乙。」 下列何項時點，視為甲已為移轉A 地所有權登記之意思表示，而無開始強制執行之必要？','判決確定時','乙已將新臺幣（下同）2,000 萬元向提存所提存時','強制執行聲請時','銀行核發乙已給付2,000 萬元之證明書時',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-4301-054','112-4301',54,'single_choice',2,'債權人甲聲請臺灣臺北地方法院民事執行處（下稱臺北地院）對債務人乙所有A 地為假扣押執行後， 乙之另一債權人丙復持假扣押裁定，聲請臺北地院對A 地為假扣押執行，臺北地院即將丙聲請假扣押 執行事件，合併於甲聲請假扣押執行程序。其後，甲撤回對A 地之假扣押執行。下列敘述，何者正確？','臺北地院應將A 地之查封登記或揭示除去，另為丙進行假扣押執行之查封程序','甲聲請假扣押執行之查封效力及於丙，臺北地院不得將A 地之查封登記或揭示除去','臺北地院應詢問丙之意見，得其同意後，對A 地再為假扣押執行之查封程序','臺北地院應得乙之同意後，對A 地再為假扣押執行之查封程序',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-4301-055','112-4301',55,'single_choice',2,'債權人甲對債務人乙有新臺幣（下同）50 萬元之執行債權，聲請法院就乙對雇主丙之每月薪資債權額 三分之一為強制執行，執行法院對丙發扣押命令。下列敘述，何者錯誤？','乙於扣押3 個月後離職，對丙無薪資債權，該扣押命令一律失其效力','該扣押命令之效力僅及於執行債權額50 萬元及其執行費用額之範圍，超過部分不生扣押之效力','該扣押命令之效力及於扣押後每月薪資，並包括嗣後調薪而增加之部分','丙收受扣押命令後，仍得與乙合意終止僱傭契約',null,'強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
